'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase-client'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { toast } from 'sonner'
import { Shield, Users, Check, X, Loader2, UserCheck, UserX, RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'

type UserProfile = {
    id: string
    full_name: string | null
    email: string | null
    role: 'admin' | 'viewer'
    created_at: string
    linked_person: string | null
}

type Contribution = {
    id: string
    content: string
    type: string
    status: string
    created_at: string
    author_id: string
}

export default function AdminPage() {
    const [profiles, setProfiles] = useState<UserProfile[]>([])
    const [contributions, setContributions] = useState<Contribution[]>([])
    const [loading, setLoading] = useState(true)
    const [isAdmin, setIsAdmin] = useState(false)
    const [currentUserId, setCurrentUserId] = useState<string | null>(null)
    const sb = createClient() as any

    useEffect(() => {
        sb.auth.getUser().then(({ data }: any) => {
            if (!data.user) return
            setCurrentUserId(data.user.id)
            sb.from('profiles').select('*').eq('id', data.user.id).single().then(({ data: p }: any) => {
                if (p?.role === 'admin') {
                    setIsAdmin(true)
                    loadData()
                } else {
                    setLoading(false)
                }
            })
        })
    }, [])

    const loadData = async () => {
        setLoading(true)
        const [{ data: users }, { data: contribs }] = await Promise.all([
            sb.from('profiles').select('*').order('created_at', { ascending: false }),
            sb.from('contributions').select('*').order('created_at', { ascending: false }).limit(20),
        ])
        setProfiles(users ?? [])
        setContributions(contribs ?? [])
        setLoading(false)
    }

    const updateRole = async (userId: string, role: 'admin' | 'viewer') => {
        try {
            await sb.from('profiles').update({ role }).eq('id', userId)
            toast.success(`Đã đổi vai trò thành ${role === 'admin' ? 'Admin' : 'Viewer'}`)
            await loadData()
        } catch (e: any) { toast.error(e.message) }
    }

    const updateContrib = async (id: string, status: 'approved' | 'rejected') => {
        try {
            await sb.from('contributions').update({ status, reviewed_at: new Date().toISOString() }).eq('id', id)
            toast.success(status === 'approved' ? 'Đã duyệt' : 'Đã từ chối')
            await loadData()
        } catch (e: any) { toast.error(e.message) }
    }

    if (!isAdmin && !loading) {
        return (
            <div className="h-full flex items-center justify-center">
                <div className="text-center space-y-3">
                    <div className="text-5xl">🔒</div>
                    <h2 className="text-lg font-bold">Không có quyền truy cập</h2>
                    <p className="text-sm text-muted-foreground">Chỉ Admin mới có thể xem trang này</p>
                </div>
            </div>
        )
    }

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                            <Shield className="w-4 h-4 text-amber-900" />
                        </div>
                        <div>
                            <h1 className="text-base font-bold leading-none">Admin Panel</h1>
                            <p className="text-xs text-muted-foreground mt-0.5">{profiles.length} người dùng</p>
                        </div>
                    </div>
                    <Button variant="outline" size="sm" className="gap-1.5 h-8 text-xs" onClick={loadData}>
                        <RefreshCw className="w-3 h-3" /> Làm mới
                    </Button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
                {loading ? (
                    <div className="flex justify-center py-12"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
                ) : (
                    <>
                        {/* Users management */}
                        <div>
                            <h2 className="text-sm font-bold mb-3 flex items-center gap-2">
                                <Users className="w-4 h-4 text-amber-500" /> Quản lý người dùng
                            </h2>
                            <div className="space-y-2">
                                {profiles.map(p => (
                                    <div key={p.id} className={cn(
                                        'glass rounded-xl p-3 border border-border/60 flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4 transition-all duration-200',
                                        p.id === currentUserId && 'border-amber-400/30'
                                    )}>
                                        <div className="flex items-center gap-3 w-full sm:w-auto flex-1 min-w-0">
                                            <div className="w-9 h-9 rounded-full gold-gradient flex items-center justify-center text-sm font-bold text-amber-900 shrink-0">
                                                {p.full_name?.[0]?.toUpperCase() ?? '?'}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <p className="text-sm font-medium truncate">{p.full_name ?? 'Chưa đặt tên'}</p>
                                                    {p.id === currentUserId && <Badge variant="outline" className="text-[10px] px-1.5 py-0">Bạn</Badge>}
                                                </div>
                                                <p className="text-xs text-muted-foreground truncate">{p.email}</p>
                                                <p className="text-[10px] text-muted-foreground">{new Date(p.created_at).toLocaleDateString('vi-VN')}</p>
                                            </div>
                                        </div>
                                        <div className="flex flex-wrap items-center gap-2 w-full sm:w-auto sm:shrink-0 pt-2 sm:pt-0 mt-2 border-t border-border/40 sm:border-0 sm:mt-0">
                                            <Badge variant={p.role === 'admin' ? 'default' : 'secondary'} className={cn('text-[10px]', p.role === 'admin' && 'bg-amber-500/20 text-amber-600 border-amber-500/30')}>
                                                {p.role === 'admin' ? '👑 Admin' : '👁 Viewer'}
                                            </Badge>
                                            {p.id !== currentUserId && (
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    className="h-7 text-xs gap-1 ml-auto sm:ml-0"
                                                    onClick={() => updateRole(p.id, p.role === 'admin' ? 'viewer' : 'admin')}
                                                >
                                                    {p.role === 'admin' ? <><UserX className="w-3 h-3" /> → Viewer</> : <><UserCheck className="w-3 h-3" /> → Admin</>}
                                                </Button>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Contributions */}
                        {contributions.length > 0 && (
                            <div>
                                <h2 className="text-sm font-bold mb-3 flex items-center gap-2">
                                    <RefreshCw className="w-4 h-4 text-amber-500" /> Đóng Góp / Đề Xuất ({contributions.filter(c => c.status === 'pending').length} chờ duyệt)
                                </h2>
                                <div className="space-y-2">
                                    {contributions.map(c => (
                                        <div key={c.id} className="glass rounded-xl p-3 border border-border/60">
                                            <div className="flex items-start justify-between gap-2">
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-xs font-medium text-muted-foreground mb-1">
                                                        {c.type === 'edit' ? '📝 Chỉnh sửa' : c.type === 'add' ? '➕ Thêm mới' : c.type === 'delete' ? '🗑️ Xoá' : '💬 Bình luận'}
                                                    </p>
                                                    <p className="text-sm text-foreground">{c.content}</p>
                                                    <p className="text-[10px] text-muted-foreground mt-1">{new Date(c.created_at).toLocaleDateString('vi-VN')}</p>
                                                </div>
                                                <div className="flex items-center gap-1 shrink-0">
                                                    <Badge variant={c.status === 'pending' ? 'outline' : c.status === 'approved' ? 'default' : 'secondary'} className="text-[10px]">
                                                        {c.status === 'pending' ? '⏳ Chờ' : c.status === 'approved' ? '✅ Đã duyệt' : '❌ Từ chối'}
                                                    </Badge>
                                                    {c.status === 'pending' && (
                                                        <div className="flex gap-1 ml-1">
                                                            <Button size="icon" variant="outline" className="h-7 w-7 hover:text-green-500" onClick={() => updateContrib(c.id, 'approved')}><Check className="w-3.5 h-3.5" /></Button>
                                                            <Button size="icon" variant="outline" className="h-7 w-7 hover:text-red-500" onClick={() => updateContrib(c.id, 'rejected')}><X className="w-3.5 h-3.5" /></Button>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    )
}

'use client'

import { useEffect, useState, useMemo } from 'react'
import { getAllPeople } from '@/lib/supabase-data'
import { Person } from '@/lib/types'
import { BookOpen, ChevronDown, ChevronRight, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

type FamilyBranch = {
    person: Person
    children: FamilyBranch[]
    spouse?: Person
}

function buildFamilyTree(people: Person[]): FamilyBranch[] {
    const map = new Map<string, Person>(people.map(p => [p.id, p]))
    const childrenOf = new Map<string, Person[]>()

    people.forEach(p => {
        const parentId = p.father_id ?? p.mother_id
        if (parentId && map.has(parentId)) {
            if (!childrenOf.has(parentId)) childrenOf.set(parentId, [])
            childrenOf.get(parentId)!.push(p)
        }
    })

    const hasParent = new Set(people.filter(p => (p.father_id && map.has(p.father_id)) || (p.mother_id && map.has(p.mother_id))).map(p => p.id))
    const roots = people.filter(p => !hasParent.has(p.id) && p.gender === 'male')

    const buildBranch = (p: Person): FamilyBranch => ({
        person: p,
        children: (childrenOf.get(p.id) ?? []).sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0)).map(buildBranch),
        spouse: p.gender === 'male' ? people.find(x => x.id !== p.id && x.gender === 'female' && (
            (childrenOf.get(p.id) ?? []).some(c => c.mother_id === x.id)
        )) : undefined,
    })

    return roots.map(buildBranch)
}

function BranchSection({ branch, depth = 0 }: { branch: FamilyBranch; depth?: number }) {
    const [open, setOpen] = useState(depth < 2)
    const { person, spouse, children } = branch
    const yearRange = [person.birth_year, person.death_year].filter(Boolean).join('–')

    return (
        <div className={cn('border-l-2 pl-4 mb-4', depth === 0 ? 'border-amber-500' : depth === 1 ? 'border-amber-400/50' : 'border-border')}>
            {/* Person header */}
            <div className="flex items-start gap-3 mb-2">
                <button
                    className="mt-0.5 text-muted-foreground hover:text-foreground"
                    onClick={() => setOpen(!open)}
                >
                    {children.length > 0
                        ? open ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />
                        : <span className="w-4 h-4 block" />
                    }
                </button>
                <div className="flex-1">
                    <div className="flex items-center gap-2 flex-wrap">
                        <span className={cn('font-bold', depth === 0 ? 'text-base text-amber-600' : depth === 1 ? 'text-sm text-amber-700/80' : 'text-sm text-foreground/90')}>
                            {person.full_name}
                        </span>
                        {yearRange && <span className="text-xs text-muted-foreground">({yearRange})</span>}
                        {!person.is_alive && <span className="text-xs text-muted-foreground/60 italic">✝</span>}
                    </div>
                    {spouse && (
                        <p className="text-xs text-muted-foreground mt-0.5">
                            ♥ <span className="font-medium">{spouse.full_name}</span>
                            {spouse.birth_year && <span className="ml-1">({[spouse.birth_year, spouse.death_year].filter(Boolean).join('–')})</span>}
                        </p>
                    )}
                    {person.notes && depth === 0 && (
                        <p className="text-xs text-muted-foreground italic mt-1 leading-relaxed">{person.notes}</p>
                    )}
                </div>
                <div className={cn(
                    'w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold shrink-0 mt-0.5',
                    'border',
                    person.gender === 'male' ? 'bg-blue-500/10 border-blue-500/30 text-blue-500' : 'bg-rose-400/10 border-rose-400/30 text-rose-400'
                )}>
                    {person.generation}
                </div>
            </div>

            {/* Children */}
            {open && children.length > 0 && (
                <div className="pl-4 space-y-0">
                    {children.map(child => (
                        <BranchSection key={child.person.id} branch={child} depth={depth + 1} />
                    ))}
                </div>
            )}
        </div>
    )
}

export default function BookPage() {
    const [people, setPeople] = useState<Person[]>([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        getAllPeople().then(data => { setPeople(data); setLoading(false) })
    }, [])

    const roots = useMemo(() => building(people), [people])
    function building(p: Person[]) { return buildFamilyTree(p) }

    const stats = useMemo(() => ({
        total: people.length,
        alive: people.filter(p => p.is_alive).length,
        gens: new Set(people.map(p => p.generation)).size,
        males: people.filter(p => p.gender === 'male').length,
        females: people.filter(p => p.gender === 'female').length,
    }), [people])

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                        <BookOpen className="w-4 h-4 text-amber-900" />
                    </div>
                    <div>
                        <h1 className="text-base font-bold leading-none">Sách Gia Phả</h1>
                        <p className="text-xs text-muted-foreground mt-0.5">Trần Tộc Mỹ Nguyên — tự động tạo từ dữ liệu</p>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-6 max-w-3xl mx-auto w-full">
                {loading ? (
                    <div className="flex justify-center py-12"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
                ) : (
                    <>
                        {/* Header */}
                        <div className="text-center mb-10 p-8 glass rounded-2xl border border-border/60">
                            <div className="text-5xl mb-4">📖</div>
                            <h2 className="text-2xl font-bold gold-text mb-2">GIA PHẢ TRẦN TỘC MỸ NGUYÊN</h2>
                            <p className="text-sm text-muted-foreground">Lưu giữ và truyền thừa qua các thế hệ</p>
                            <div className="grid grid-cols-3 gap-4 mt-6">
                                <div className="text-center">
                                    <div className="text-xl font-bold text-amber-500">{stats.total}</div>
                                    <div className="text-xs text-muted-foreground">Thành viên</div>
                                </div>
                                <div className="text-center">
                                    <div className="text-xl font-bold text-amber-500">{stats.gens}</div>
                                    <div className="text-xs text-muted-foreground">Thế hệ</div>
                                </div>
                                <div className="text-center">
                                    <div className="text-xl font-bold text-amber-500">{stats.alive}</div>
                                    <div className="text-xs text-muted-foreground">Còn sống</div>
                                </div>
                            </div>
                        </div>

                        {/* Family tree book format */}
                        <div className="space-y-2">
                            <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-4">Phả Hệ</h3>
                            {roots.map(branch => (
                                <BranchSection key={branch.person.id} branch={branch} depth={0} />
                            ))}
                        </div>

                        {/* All members by generation */}
                        <div className="mt-10 pt-6 border-t border-border">
                            <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-4">Danh Sách Theo Thế Hệ</h3>
                            {Array.from(new Set(people.map(p => p.generation))).sort().map(gen => (
                                <div key={gen} className="glass rounded-xl p-4 border border-border/60">
                                    <p className="text-sm font-semibold text-amber-700 mb-1">Thế hệ thứ {gen}</p>
                                    <p className="text-xs text-muted-foreground">{people.filter(p => p.generation === gen).length} thành viên ({people.filter(p => p.generation === gen && !p.is_alive).length} đã mất)</p>
                                    <div className="space-y-1 mt-2">
                                        {people.filter(p => p.generation === gen).map(p => (
                                            <div key={p.id} className="flex items-center gap-2 text-sm text-foreground/80 pl-3">
                                                <span>{p.gender === 'male' ? '♂' : p.gender === 'female' ? '♀' : '—'}</span>
                                                <span className="font-medium">{p.full_name}</span>
                                                {(p.birth_year || p.death_year) && (
                                                    <span className="text-xs text-muted-foreground">
                                                        ({[p.birth_year, p.death_year].filter(Boolean).join('–')})
                                                    </span>
                                                )}
                                                {!p.is_alive && <span className="text-xs text-muted-foreground">✝</span>}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </>
                )}
            </div>
        </div>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { getAllPeople } from '@/lib/supabase-data'
import { Person } from '@/lib/types'
import { createClient } from '@/lib/supabase-client'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { Phone, Search, Pencil, Loader2, MessageCircle, Mail, MapPin } from 'lucide-react'
import { cn } from '@/lib/utils'

type Contact = {
    id: string
    person_id: string
    phone: string | null
    zalo: string | null
    facebook: string | null
    email: string | null
    address: string | null
    notes: string | null
}

type PersonWithContact = Person & { contact?: Contact }

export default function DirectoryPage() {
    const [people, setPeople] = useState<PersonWithContact[]>([])
    const [filtered, setFiltered] = useState<PersonWithContact[]>([])
    const [query, setQuery] = useState('')
    const [loading, setLoading] = useState(true)
    const [isAdmin, setIsAdmin] = useState(false)
    const [editPerson, setEditPerson] = useState<PersonWithContact | null>(null)
    const [form, setForm] = useState({ phone: '', zalo: '', facebook: '', email: '', address: '', notes: '' })
    const [saving, setSaving] = useState(false)
    const sb = createClient() as any

    const load = async () => {
        setLoading(true)
        const allPeople = await getAllPeople()
        const { data: contacts } = await sb.from('contacts').select('*')
        const contactMap = new Map((contacts ?? []).map((c: Contact) => [c.person_id, c]))
        const merged = allPeople.map(p => ({ ...p, contact: contactMap.get(p.id) as Contact | undefined }))
        setPeople(merged)
        setFiltered(merged)
        setLoading(false)
    }

    useEffect(() => { load() }, [])

    useEffect(() => {
        sb.auth.getUser().then(({ data }: any) => {
            if (!data.user) return
            sb.from('profiles').select('*').eq('id', data.user.id).single().then(({ data: p }: any) => {
                setIsAdmin(p?.role === 'admin')
            })
        })
    }, [])

    useEffect(() => {
        if (!query.trim()) { setFiltered(people); return }
        const q = query.toLowerCase()
        setFiltered(people.filter(p => p.full_name.toLowerCase().includes(q) || p.contact?.phone?.includes(q) || p.contact?.email?.toLowerCase().includes(q)))
    }, [query, people])

    const openEdit = (p: PersonWithContact) => {
        setEditPerson(p)
        setForm({
            phone: p.contact?.phone ?? '',
            zalo: p.contact?.zalo ?? '',
            facebook: p.contact?.facebook ?? '',
            email: p.contact?.email ?? '',
            address: p.contact?.address ?? '',
            notes: p.contact?.notes ?? '',
        })
    }

    const handleSave = async () => {
        if (!editPerson) return
        setSaving(true)
        try {
            const existing = editPerson.contact
            if (existing) {
                await sb.from('contacts').update({ ...form, updated_at: new Date().toISOString() }).eq('id', existing.id)
            } else {
                await sb.from('contacts').insert({ ...form, person_id: editPerson.id })
            }
            toast.success('Đã lưu thông tin liên lạc')
            setEditPerson(null)
            await load()
        } catch (e: any) {
            toast.error(e.message)
        }
        setSaving(false)
    }

    const withContact = filtered.filter(p => p.contact)
    const withoutContact = filtered.filter(p => !p.contact)

    const ContactCard = ({ p }: { p: PersonWithContact }) => (
        <div className={cn(
            'glass rounded-xl p-4 border border-border/60 hover:border-amber-400/40 transition-all group',
            !p.is_alive && 'opacity-60'
        )}>
            <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className={cn(
                        'w-10 h-10 rounded-lg flex items-center justify-center text-xl shrink-0 border',
                        p.gender === 'male' ? 'bg-blue-500/10 border-blue-500/30' :
                            p.gender === 'female' ? 'bg-rose-400/10 border-rose-400/30' : 'bg-muted border-border'
                    )}>
                        {p.gender === 'male' ? '👨' : p.gender === 'female' ? '👩' : '👤'}
                    </div>
                    <div className="flex-1 min-w-0">
                        <p className="font-semibold text-sm truncate">{p.full_name}</p>
                        <p className="text-xs text-muted-foreground">Thế hệ {p.generation}</p>
                    </div>
                </div>
                {isAdmin && (
                    <Button variant="ghost" size="icon" className="h-7 w-7 opacity-0 group-hover:opacity-100 hover:text-amber-500 shrink-0"
                        onClick={() => openEdit(p)}>
                        <Pencil className="w-3.5 h-3.5" />
                    </Button>
                )}
            </div>

            {p.contact ? (
                <div className="mt-3 space-y-1.5">
                    {p.contact.phone && (
                        <a href={`tel:${p.contact.phone}`} className="flex items-center gap-2 text-xs text-muted-foreground hover:text-foreground transition-colors">
                            <Phone className="w-3 h-3" /> {p.contact.phone}
                        </a>
                    )}
                    {p.contact.zalo && (
                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                            <MessageCircle className="w-3 h-3 text-blue-400" />
                            <span>Zalo: {p.contact.zalo}</span>
                        </div>
                    )}
                    {p.contact.email && (
                        <a href={`mailto:${p.contact.email}`} className="flex items-center gap-2 text-xs text-muted-foreground hover:text-foreground transition-colors">
                            <Mail className="w-3 h-3" /> {p.contact.email}
                        </a>
                    )}
                    {p.contact.address && (
                        <div className="flex items-start gap-2 text-xs text-muted-foreground">
                            <MapPin className="w-3 h-3 mt-0.5 shrink-0" /> {p.contact.address}
                        </div>
                    )}
                </div>
            ) : (
                <div className="mt-3 flex items-center justify-between">
                    <p className="text-xs text-muted-foreground italic">Chưa có thông tin liên lạc</p>
                    {isAdmin && (
                        <Button variant="ghost" size="sm" className="h-6 text-[10px] text-amber-500 hover:text-amber-400 px-2" onClick={() => openEdit(p)}>
                            + Thêm
                        </Button>
                    )}
                </div>
            )}
        </div>
    )

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center gap-3 mb-3">
                    <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                        <Phone className="w-4 h-4 text-amber-900" />
                    </div>
                    <div>
                        <h1 className="text-base font-bold leading-none">Danh Bạ</h1>
                        <p className="text-xs text-muted-foreground mt-0.5">{withContact.length}/{people.length} thành viên có thông tin</p>
                    </div>
                </div>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
                    <Input placeholder="Tìm theo tên, số điện thoại, email..." value={query} onChange={e => setQuery(e.target.value)} className="pl-9 h-8 text-sm" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-4">
                {loading ? (
                    <div className="flex justify-center py-12"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
                ) : (
                    <div className="space-y-6">
                        {withContact.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold text-muted-foreground mb-3 uppercase tracking-wider">Có thông tin liên lạc ({withContact.length})</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                    {withContact.map(p => <ContactCard key={p.id} p={p} />)}
                                </div>
                            </div>
                        )}
                        {isAdmin && withoutContact.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold text-muted-foreground mb-3 uppercase tracking-wider">Chưa có thông tin ({withoutContact.length})</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                    {withoutContact.map(p => <ContactCard key={p.id} p={p} />)}
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <Dialog open={!!editPerson} onOpenChange={v => !v && setEditPerson(null)}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle>Thông tin liên lạc — {editPerson?.full_name}</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-3 py-2">
                        {[
                            { key: 'phone', label: 'Số điện thoại', placeholder: '09xxxxxxxx' },
                            { key: 'zalo', label: 'Zalo', placeholder: 'Số Zalo hoặc username' },
                            { key: 'facebook', label: 'Facebook', placeholder: 'Link profile Facebook' },
                            { key: 'email', label: 'Email', placeholder: 'email@example.com' },
                            { key: 'address', label: 'Địa chỉ', placeholder: 'Địa chỉ thường trú' },
                            { key: 'notes', label: 'Ghi chú', placeholder: 'Thông tin khác...' },
                        ].map(({ key, label, placeholder }) => (
                            <div key={key} className="space-y-1">
                                <Label>{label}</Label>
                                <Input value={(form as any)[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))} placeholder={placeholder} />
                            </div>
                        ))}
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setEditPerson(null)}>Hủy</Button>
                        <Button className="gold-gradient border-0 text-amber-950" onClick={handleSave} disabled={saving}>
                            {saving && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                            Lưu
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase-client'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { toast } from 'sonner'
import { CalendarDays, Plus, Loader2, MapPin, Clock, Pencil, Trash2 } from 'lucide-react'
import { cn } from '@/lib/utils'

type Event = {
    id: string
    title: string
    description: string | null
    event_date: string
    event_time: string | null
    location: string | null
    type: string
    created_at: string
}

const EVENT_TYPES: Record<string, { label: string; emoji: string; color: string }> = {
    gio_to: { label: 'Giỗ Tổ', emoji: '🕯️', color: 'text-red-500 bg-red-500/10 border-red-500/30' },
    dam_cuoi: { label: 'Đám Cưới', emoji: '💒', color: 'text-rose-400 bg-rose-400/10 border-rose-400/30' },
    sinh_nhat: { label: 'Sinh Nhật', emoji: '🎂', color: 'text-amber-500 bg-amber-500/10 border-amber-500/30' },
    tang_le: { label: 'Tang Lễ', emoji: '🪔', color: 'text-slate-400 bg-slate-400/10 border-slate-400/30' },
    hop_mat: { label: 'Họp Mặt', emoji: '🎉', color: 'text-green-500 bg-green-500/10 border-green-500/30' },
    khac: { label: 'Khác', emoji: '📌', color: 'text-muted-foreground bg-muted border-border' },
}

const EMPTY_FORM = { title: '', description: '', event_date: '', event_time: '', location: '', type: 'khac' }

export default function EventsPage() {
    const [events, setEvents] = useState<Event[]>([])
    const [loading, setLoading] = useState(true)
    const [isAdmin, setIsAdmin] = useState(false)
    const [dialogOpen, setDialogOpen] = useState(false)
    const [editTarget, setEditTarget] = useState<Event | null>(null)
    const [form, setForm] = useState(EMPTY_FORM)
    const [saving, setSaving] = useState(false)
    const sb = createClient() as any

    const load = async () => {
        setLoading(true)
        const { data } = await sb.from('events').select('*').order('event_date', { ascending: true })
        setEvents(data ?? [])
        setLoading(false)
    }

    useEffect(() => { load() }, [])
    useEffect(() => {
        sb.auth.getUser().then(({ data }: any) => {
            if (!data.user) return
            sb.from('profiles').select('*').eq('id', data.user.id).single().then(({ data: p }: any) => {
                setIsAdmin(p?.role === 'admin')
            })
        })
    }, [])

    const openAdd = () => { setEditTarget(null); setForm(EMPTY_FORM); setDialogOpen(true) }
    const openEdit = (e: Event) => {
        setEditTarget(e)
        setForm({ title: e.title, description: e.description ?? '', event_date: e.event_date, event_time: e.event_time ?? '', location: e.location ?? '', type: e.type })
        setDialogOpen(true)
    }

    const handleSave = async () => {
        if (!form.title || !form.event_date) { toast.error('Vui lòng nhập tên và ngày'); return }
        setSaving(true)
        try {
            if (editTarget) {
                await sb.from('events').update({ ...form, event_time: form.event_time || null, description: form.description || null, location: form.location || null, updated_at: new Date().toISOString() }).eq('id', editTarget.id)
                toast.success('Đã cập nhật sự kiện')
            } else {
                await sb.from('events').insert({ ...form, event_time: form.event_time || null, description: form.description || null, location: form.location || null })
                toast.success('Đã thêm sự kiện mới')
            }
            setDialogOpen(false)
            await load()
        } catch (e: any) { toast.error(e.message) }
        setSaving(false)
    }

    const handleDelete = async (e: Event) => {
        if (!confirm(`Xoá "${e.title}"?`)) return
        await sb.from('events').delete().eq('id', e.id)
        toast.success('Đã xoá')
        await load()
    }

    const now = new Date()
    const upcoming = events.filter(e => new Date(e.event_date) >= now)
    const past = events.filter(e => new Date(e.event_date) < now)

    const formatDate = (d: string) => new Date(d).toLocaleDateString('vi-VN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
    const daysUntil = (d: string) => {
        const diff = Math.ceil((new Date(d).getTime() - now.getTime()) / 86400000)
        if (diff === 0) return 'Hôm nay'
        if (diff === 1) return 'Ngày mai'
        if (diff > 0) return `${diff} ngày nữa`
        return `${Math.abs(diff)} ngày trước`
    }

    const EventCard = ({ e }: { e: Event }) => {
        const meta = EVENT_TYPES[e.type] ?? EVENT_TYPES.khac
        const isPast = new Date(e.event_date) < now
        return (
            <div className={cn('glass rounded-xl p-4 border transition-all group', isPast ? 'opacity-60 border-border/40' : 'border-border/60 hover:border-amber-400/40')}>
                <div className="flex items-start justify-between gap-2">
                    <div className="flex items-start gap-3 flex-1 min-w-0">
                        <div className="text-2xl mt-0.5 shrink-0">{meta.emoji}</div>
                        <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                                <p className="font-semibold text-sm">{e.title}</p>
                                <Badge variant="outline" className={cn('text-[10px] px-1.5 py-0 border', meta.color)}>
                                    {meta.label}
                                </Badge>
                            </div>
                            <p className="text-xs text-muted-foreground mt-1">{formatDate(e.event_date)}</p>
                            {!isPast && (
                                <p className="text-xs font-semibold text-amber-600 mt-0.5">{daysUntil(e.event_date)}</p>
                            )}
                            {e.event_time && (
                                <div className="flex items-center gap-1 text-xs text-muted-foreground mt-1">
                                    <Clock className="w-3 h-3" /> {e.event_time}
                                </div>
                            )}
                            {e.location && (
                                <div className="flex items-center gap-1 text-xs text-muted-foreground mt-1">
                                    <MapPin className="w-3 h-3 shrink-0" /> {e.location}
                                </div>
                            )}
                            {e.description && <p className="text-xs text-muted-foreground mt-1 italic">{e.description}</p>}
                        </div>
                    </div>
                    {isAdmin && (
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                            <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-amber-500" onClick={() => openEdit(e)}><Pencil className="w-3.5 h-3.5" /></Button>
                            <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-red-500" onClick={() => handleDelete(e)}><Trash2 className="w-3.5 h-3.5" /></Button>
                        </div>
                    )}
                </div>
            </div>
        )
    }

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                            <CalendarDays className="w-4 h-4 text-amber-900" />
                        </div>
                        <div>
                            <h1 className="text-base font-bold leading-none">Sự Kiện</h1>
                            <p className="text-xs text-muted-foreground mt-0.5">{upcoming.length} sự kiện sắp tới</p>
                        </div>
                    </div>
                    {isAdmin && (
                        <Button size="sm" className="gold-gradient border-0 text-amber-950 font-semibold hover:opacity-90 gap-1.5" onClick={openAdd}>
                            <Plus className="w-3.5 h-3.5" /> Thêm sự kiện
                        </Button>
                    )}
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
                {loading ? (
                    <div className="flex justify-center py-12"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
                ) : (
                    <>
                        {upcoming.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">Sắp tới ({upcoming.length})</p>
                                <div className="space-y-3">{upcoming.map(e => <EventCard key={e.id} e={e} />)}</div>
                            </div>
                        )}
                        {past.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">Đã qua ({past.length})</p>
                                <div className="space-y-3">{past.map(e => <EventCard key={e.id} e={e} />)}</div>
                            </div>
                        )}
                        {events.length === 0 && (
                            <p className="text-center text-muted-foreground py-12">Chưa có sự kiện nào</p>
                        )}
                    </>
                )}
            </div>

            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                <DialogContent className="max-w-md">
                    <DialogHeader><DialogTitle>{editTarget ? 'Chỉnh sửa sự kiện' : 'Thêm sự kiện mới'}</DialogTitle></DialogHeader>
                    <div className="space-y-3 py-2">
                        <div className="space-y-1"><Label>Tên sự kiện *</Label><Input value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} placeholder="Giỗ Tổ Trần Tộc..." /></div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                                <Label>Ngày *</Label>
                                <Input type="date" value={form.event_date} onChange={e => setForm(f => ({ ...f, event_date: e.target.value }))} />
                            </div>
                            <div className="space-y-1">
                                <Label>Giờ</Label>
                                <Input type="time" value={form.event_time} onChange={e => setForm(f => ({ ...f, event_time: e.target.value }))} />
                            </div>
                        </div>
                        <div className="space-y-1">
                            <Label>Loại sự kiện</Label>
                            <select value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value }))} className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm">
                                {Object.entries(EVENT_TYPES).map(([k, v]) => <option key={k} value={k}>{v.emoji} {v.label}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1"><Label>Địa điểm</Label><Input value={form.location} onChange={e => setForm(f => ({ ...f, location: e.target.value }))} placeholder="Nhà thờ họ, địa chỉ..." /></div>
                        <div className="space-y-1"><Label>Mô tả</Label><Input value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} placeholder="Chi tiết sự kiện..." /></div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDialogOpen(false)}>Hủy</Button>
                        <Button className="gold-gradient border-0 text-amber-950" onClick={handleSave} disabled={saving}>
                            {saving && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                            {editTarget ? 'Lưu' : 'Thêm'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase-client'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { toast } from 'sonner'
import { ImageIcon, Plus, Loader2, Trash2, Search, X } from 'lucide-react'
import { cn } from '@/lib/utils'

type Media = {
    id: string
    title: string
    description: string | null
    url: string
    type: 'image' | 'video'
    year: number | null
    created_at: string
}

const EMPTY_FORM = { title: '', description: '', url: '', type: 'image' as 'image' | 'video', year: '' }

export default function MediaPage() {
    const [media, setMedia] = useState<Media[]>([])
    const [filtered, setFiltered] = useState<Media[]>([])
    const [query, setQuery] = useState('')
    const [loading, setLoading] = useState(true)
    const [isAdmin, setIsAdmin] = useState(false)
    const [dialogOpen, setDialogOpen] = useState(false)
    const [form, setForm] = useState(EMPTY_FORM)
    const [saving, setSaving] = useState(false)
    const [selected, setSelected] = useState<Media | null>(null)
    const sb = createClient() as any

    const load = async () => {
        setLoading(true)
        const { data } = await sb.from('media').select('*').order('created_at', { ascending: false })
        setMedia(data ?? [])
        setFiltered(data ?? [])
        setLoading(false)
    }

    useEffect(() => { load() }, [])
    useEffect(() => {
        sb.auth.getUser().then(({ data }: any) => {
            if (!data.user) return
            sb.from('profiles').select('*').eq('id', data.user.id).single().then(({ data: p }: any) => setIsAdmin(p?.role === 'admin'))
        })
    }, [])

    useEffect(() => {
        if (!query.trim()) { setFiltered(media); return }
        const q = query.toLowerCase()
        setFiltered(media.filter(m => m.title.toLowerCase().includes(q) || m.description?.toLowerCase().includes(q)))
    }, [query, media])

    const handleSave = async () => {
        if (!form.title || !form.url) { toast.error('Vui lòng nhập tên và URL'); return }
        setSaving(true)
        try {
            await sb.from('media').insert({ ...form, year: form.year ? parseInt(form.year) : null, description: form.description || null })
            toast.success('Đã thêm vào thư viện')
            setDialogOpen(false)
            setForm(EMPTY_FORM)
            await load()
        } catch (e: any) { toast.error(e.message) }
        setSaving(false)
    }

    const handleDelete = async (m: Media) => {
        if (!confirm(`Xoá "${m.title}"?`)) return
        await sb.from('media').delete().eq('id', m.id)
        toast.success('Đã xoá')
        await load()
    }

    const images = filtered.filter(m => m.type === 'image')
    const videos = filtered.filter(m => m.type === 'video')

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                            <ImageIcon className="w-4 h-4 text-amber-900" />
                        </div>
                        <div>
                            <h1 className="text-base font-bold leading-none">Thư Viện</h1>
                            <p className="text-xs text-muted-foreground mt-0.5">{media.length} ảnh & video dòng họ</p>
                        </div>
                    </div>
                    {isAdmin && (
                        <Button size="sm" className="gold-gradient border-0 text-amber-950 font-semibold hover:opacity-90 gap-1.5" onClick={() => setDialogOpen(true)}>
                            <Plus className="w-3.5 h-3.5" /> Thêm media
                        </Button>
                    )}
                </div>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
                    <Input placeholder="Tìm kiếm..." value={query} onChange={e => setQuery(e.target.value)} className="pl-9 h-8 text-sm" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-4">
                {loading ? (
                    <div className="flex justify-center py-12"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
                ) : media.length === 0 ? (
                    <div className="text-center py-16 text-muted-foreground">
                        <div className="text-5xl mb-4">📷</div>
                        <p className="text-sm">Chưa có ảnh hoặc video nào</p>
                        {isAdmin && <p className="text-xs mt-2">Nhấn <span className="text-amber-500">+ Thêm media</span> để bắt đầu</p>}
                    </div>
                ) : (
                    <div className="space-y-6">
                        {images.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">Hình ảnh ({images.length})</p>
                                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                                    {images.map(m => (
                                        <div key={m.id} className="relative group aspect-square rounded-xl overflow-hidden border border-border/60 cursor-pointer" onClick={() => setSelected(m)}>
                                            <img src={m.url} alt={m.title} className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105" onError={e => { (e.target as any).src = 'https://placehold.co/400x400/92400e/fbbf24?text=📷' }} />
                                            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                                                <div className="absolute bottom-0 left-0 right-0 p-2">
                                                    <p className="text-white text-xs font-medium truncate">{m.title}</p>
                                                    {m.year && <p className="text-white/70 text-[10px]">{m.year}</p>}
                                                </div>
                                            </div>
                                            {isAdmin && (
                                                <button className="absolute top-2 right-2 w-6 h-6 rounded-md bg-red-500/80 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center hover:bg-red-600"
                                                    onClick={ev => { ev.stopPropagation(); handleDelete(m) }}>
                                                    <Trash2 className="w-3 h-3" />
                                                </button>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                        {videos.length > 0 && (
                            <div>
                                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">Video ({videos.length})</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    {videos.map(m => (
                                        <div key={m.id} className="glass rounded-xl p-4 border border-border/60 group">
                                            <div className="flex items-center gap-3">
                                                <div className="w-12 h-12 rounded-lg bg-muted flex items-center justify-center text-2xl shrink-0">🎬</div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="font-medium text-sm truncate">{m.title}</p>
                                                    {m.year && <p className="text-xs text-muted-foreground">{m.year}</p>}
                                                    {m.description && <p className="text-xs text-muted-foreground italic truncate">{m.description}</p>}
                                                </div>
                                                {isAdmin && (
                                                    <Button variant="ghost" size="icon" className="h-7 w-7 opacity-0 group-hover:opacity-100 hover:text-red-500" onClick={() => handleDelete(m)}>
                                                        <Trash2 className="w-3.5 h-3.5" />
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Image lightbox */}
            {selected && (
                <div className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4" onClick={() => setSelected(null)}>
                    <button className="absolute top-4 right-4 text-white/70 hover:text-white" onClick={() => setSelected(null)}>
                        <X className="w-6 h-6" />
                    </button>
                    <div className="max-w-4xl w-full" onClick={e => e.stopPropagation()}>
                        <img src={selected.url} alt={selected.title} className="w-full max-h-[80vh] object-contain rounded-xl" />
                        <div className="text-center mt-4">
                            <p className="text-white font-semibold">{selected.title}</p>
                            {selected.year && <p className="text-white/70 text-sm">{selected.year}</p>}
                            {selected.description && <p className="text-white/60 text-sm italic mt-1">{selected.description}</p>}
                        </div>
                    </div>
                </div>
            )}

            {/* Add dialog */}
            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                <DialogContent className="max-w-md">
                    <DialogHeader><DialogTitle>Thêm ảnh / video</DialogTitle></DialogHeader>
                    <div className="space-y-3 py-2">
                        <div className="space-y-1"><Label>Tiêu đề *</Label><Input value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} placeholder="Họp mặt Tết 2025..." /></div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                                <Label>Loại</Label>
                                <select value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value as any }))} className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm">
                                    <option value="image">🖼️ Hình ảnh</option>
                                    <option value="video">🎬 Video</option>
                                </select>
                            </div>
                            <div className="space-y-1"><Label>Năm</Label><Input type="number" placeholder="2025" value={form.year} onChange={e => setForm(f => ({ ...f, year: e.target.value }))} /></div>
                        </div>
                        <div className="space-y-1"><Label>URL ảnh / video *</Label><Input value={form.url} onChange={e => setForm(f => ({ ...f, url: e.target.value }))} placeholder="https://..." /></div>
                        <div className="space-y-1"><Label>Mô tả</Label><Input value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} placeholder="Mô tả thêm..." /></div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDialogOpen(false)}>Hủy</Button>
                        <Button className="gold-gradient border-0 text-amber-950" onClick={handleSave} disabled={saving}>
                            {saving && <Loader2 className="w-4 h-4 animate-spin mr-2" />} Thêm
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { getAllPeople, createPerson, updatePerson, deletePerson, searchPeople } from '@/lib/supabase-data'
import { Person, PersonInsert } from '@/lib/types'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { toast } from 'sonner'
import { Plus, Search, Pencil, Trash2, Loader2, Users } from 'lucide-react'
import { cn } from '@/lib/utils'
import { createClient } from '@/lib/supabase-client'

type FormData = {
    full_name: string
    gender: 'male' | 'female' | 'unknown'
    birth_year: string
    death_year: string
    is_alive: boolean
    generation: string
    notes: string
    father_id: string
    mother_id: string
}

const EMPTY_FORM: FormData = {
    full_name: '', gender: 'unknown', birth_year: '', death_year: '',
    is_alive: true, generation: '1', notes: '', father_id: '', mother_id: ''
}

export default function PeoplePage() {
    const [people, setPeople] = useState<Person[]>([])
    const [filtered, setFiltered] = useState<Person[]>([])
    const [query, setQuery] = useState('')
    const [loading, setLoading] = useState(true)
    const [isAdmin, setIsAdmin] = useState(false)
    const [dialogOpen, setDialogOpen] = useState(false)
    const [editTarget, setEditTarget] = useState<Person | null>(null)
    const [form, setForm] = useState<FormData>(EMPTY_FORM)
    const [saving, setSaving] = useState(false)

    const load = useCallback(async () => {
        setLoading(true)
        const data = await getAllPeople()
        setPeople(data)
        setFiltered(data)
        setLoading(false)
    }, [])

    useEffect(() => { load() }, [load])

    useEffect(() => {
        const sb = createClient()
        sb.auth.getUser().then(({ data }) => {
            if (!data.user) return
            sb.from('profiles').select('*').eq('id', data.user.id).single().then(({ data: p }) => {
                setIsAdmin((p as any)?.role === 'admin')
            })
        })
    }, [])

    useEffect(() => {
        if (!query.trim()) { setFiltered(people); return }
        const q = query.toLowerCase()
        setFiltered(people.filter(p => p.full_name.toLowerCase().includes(q)))
    }, [query, people])

    const openAdd = () => { setEditTarget(null); setForm(EMPTY_FORM); setDialogOpen(true) }
    const openEdit = (p: Person) => {
        setEditTarget(p)
        setForm({
            full_name: p.full_name, gender: p.gender, birth_year: String(p.birth_year ?? ''),
            death_year: String(p.death_year ?? ''), is_alive: p.is_alive,
            generation: String(p.generation), notes: p.notes ?? '',
            father_id: p.father_id ?? '', mother_id: p.mother_id ?? '',
        })
        setDialogOpen(true)
    }

    const handleSave = async () => {
        if (!form.full_name.trim()) { toast.error('Vui lòng nhập tên'); return }
        setSaving(true)
        const payload: PersonInsert = {
            full_name: form.full_name.trim(),
            gender: form.gender,
            birth_year: form.birth_year ? parseInt(form.birth_year) : null,
            death_year: form.death_year ? parseInt(form.death_year) : null,
            is_alive: form.is_alive,
            generation: parseInt(form.generation) || 1,
            notes: form.notes.trim() || null,
            father_id: form.father_id || null,
            mother_id: form.mother_id || null,
            avatar_url: null, sort_order: 0,
        }
        try {
            if (editTarget) {
                await updatePerson(editTarget.id, payload)
                toast.success('Đã cập nhật thông tin')
            } else {
                await createPerson(payload)
                toast.success('Đã thêm thành viên mới')
            }
            setDialogOpen(false)
            await load()
        } catch (e: any) {
            toast.error(e.message || 'Có lỗi xảy ra')
        }
        setSaving(false)
    }

    const handleDelete = async (p: Person) => {
        if (!confirm(`Xoá "${p.full_name}"? Hành động này không thể hoàn tác.`)) return
        try {
            await deletePerson(p.id)
            toast.success('Đã xoá thành viên')
            await load()
        } catch (e: any) {
            toast.error(e.message)
        }
    }

    const genderLabel = (g: string) => g === 'male' ? '♂ Nam' : g === 'female' ? '♀ Nữ' : '— Khác'
    const genderClass = (g: string) => g === 'male' ? 'text-blue-500' : g === 'female' ? 'text-rose-400' : 'text-muted-foreground'

    const byGen = filtered.reduce<Record<number, Person[]>>((acc, p) => {
        const g = p.generation ?? 1;
        (acc[g] = acc[g] || []).push(p)
        return acc
    }, {})

    return (
        <div className="h-full flex flex-col">
            {/* Header */}
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                            <Users className="w-4 h-4 text-amber-900" />
                        </div>
                        <div>
                            <h1 className="text-base font-bold leading-none">Thành Viên</h1>
                            <p className="text-xs text-muted-foreground mt-0.5">{people.length} người trong dòng họ</p>
                        </div>
                    </div>
                    {isAdmin && (
                        <Button size="sm" className="gold-gradient border-0 text-amber-950 font-semibold hover:opacity-90 gap-1.5" onClick={openAdd}>
                            <Plus className="w-3.5 h-3.5" /> Thêm thành viên
                        </Button>
                    )}
                </div>
                {/* Search */}
                <div className="relative mt-3">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
                    <Input placeholder="Tìm kiếm theo tên..." value={query} onChange={e => setQuery(e.target.value)} className="pl-9 h-8 text-sm" />
                </div>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
                {loading ? (
                    <div className="flex justify-center py-12">
                        <Loader2 className="w-6 h-6 animate-spin text-primary" />
                    </div>
                ) : Object.keys(byGen).length === 0 ? (
                    <p className="text-center text-muted-foreground py-12">Không tìm thấy thành viên nào</p>
                ) : (
                    Object.entries(byGen).sort(([a], [b]) => parseInt(a) - parseInt(b)).map(([gen, members]) => (
                        <div key={gen}>
                            <div className="flex items-center gap-2 mb-3">
                                <div className="h-px flex-1 bg-border" />
                                <span className="text-xs font-semibold text-muted-foreground px-2">Thế hệ {gen}</span>
                                <div className="h-px flex-1 bg-border" />
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                {members.map(p => (
                                    <div key={p.id} className={cn(
                                        'glass rounded-xl p-4 border border-border/60 hover:border-amber-400/40 transition-all duration-200 group',
                                        !p.is_alive && 'opacity-60'
                                    )}>
                                        <div className="flex items-start justify-between gap-2">
                                            <div className="flex items-center gap-3 flex-1 min-w-0">
                                                <div className={cn(
                                                    'w-10 h-10 rounded-lg flex items-center justify-center text-xl shrink-0 border',
                                                    p.gender === 'male' ? 'bg-blue-500/10 border-blue-500/30' :
                                                        p.gender === 'female' ? 'bg-rose-400/10 border-rose-400/30' : 'bg-muted border-border'
                                                )}>
                                                    {p.gender === 'male' ? '👨' : p.gender === 'female' ? '👩' : '👤'}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="font-semibold text-sm truncate">{p.full_name}</p>
                                                    <p className={cn('text-xs', genderClass(p.gender))}>{genderLabel(p.gender)}</p>
                                                    {(p.birth_year || p.death_year) && (
                                                        <p className="text-xs text-muted-foreground mt-0.5">
                                                            {[p.birth_year, p.death_year].filter(Boolean).join(' – ')}
                                                        </p>
                                                    )}
                                                </div>
                                            </div>
                                            {isAdmin && (
                                                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-amber-500" onClick={() => openEdit(p)}>
                                                        <Pencil className="w-3.5 h-3.5" />
                                                    </Button>
                                                    <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-red-500" onClick={() => handleDelete(p)}>
                                                        <Trash2 className="w-3.5 h-3.5" />
                                                    </Button>
                                                </div>
                                            )}
                                        </div>
                                        {!p.is_alive && <Badge variant="secondary" className="mt-2 text-[10px]">Đã mất</Badge>}
                                        {p.notes && <p className="text-xs text-muted-foreground mt-2 italic line-clamp-2">{p.notes}</p>}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Add/Edit Dialog */}
            <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle>{editTarget ? 'Chỉnh sửa thành viên' : 'Thêm thành viên mới'}</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-3 py-2">
                        <div className="space-y-1">
                            <Label>Họ và tên *</Label>
                            <Input value={form.full_name} onChange={e => setForm(f => ({ ...f, full_name: e.target.value }))} placeholder="Trần Văn A" />
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                                <Label>Giới tính</Label>
                                <select value={form.gender} onChange={e => setForm(f => ({ ...f, gender: e.target.value as any }))}
                                    className="w-full h-9 px-3 rounded-md border border-input bg-background text-sm">
                                    <option value="male">Nam</option>
                                    <option value="female">Nữ</option>
                                    <option value="unknown">Khác</option>
                                </select>
                            </div>
                            <div className="space-y-1">
                                <Label>Thế hệ</Label>
                                <Input type="number" min="1" value={form.generation} onChange={e => setForm(f => ({ ...f, generation: e.target.value }))} />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                                <Label>Năm sinh</Label>
                                <Input type="number" placeholder="1950" value={form.birth_year} onChange={e => setForm(f => ({ ...f, birth_year: e.target.value }))} />
                            </div>
                            <div className="space-y-1">
                                <Label>Năm mất</Label>
                                <Input type="number" placeholder="2020" value={form.death_year} onChange={e => setForm(f => ({ ...f, death_year: e.target.value, is_alive: !e.target.value }))} />
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <input type="checkbox" id="alive" checked={form.is_alive} onChange={e => setForm(f => ({ ...f, is_alive: e.target.checked, death_year: e.target.checked ? '' : f.death_year }))} className="rounded" />
                            <Label htmlFor="alive" className="cursor-pointer">Còn sống</Label>
                        </div>
                        <div className="space-y-1">
                            <Label>Ghi chú</Label>
                            <Input value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} placeholder="Thông tin thêm..." />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDialogOpen(false)}>Hủy</Button>
                        <Button className="gold-gradient border-0 text-amber-950" onClick={handleSave} disabled={saving}>
                            {saving && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                            {editTarget ? 'Lưu thay đổi' : 'Thêm mới'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    )
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
    ReactFlow,
    Background,
    Controls,
    MiniMap,
    useNodesState,
    useEdgesState,
    type NodeMouseHandler,
    ReactFlowProvider,
    useReactFlow,
    type Node,
    type Edge,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { PersonNode } from '@/components/tree/person-node'
import { buildTreeLayout, type PersonNode as PersonNodeType } from '@/lib/tree-layout'
import { getAllPeople } from '@/lib/supabase-data'
import { Person } from '@/lib/types'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Search, X, Users, GitBranch } from 'lucide-react'
import { cn } from '@/lib/utils'

const nodeTypes = { person: PersonNode }

function PersonDetailPanel({ person, onClose }: { person: Person; onClose: () => void }) {
    return (
        <div className="absolute right-4 top-4 z-20 w-64 glass rounded-xl p-4 shadow-xl border border-border">
            <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-2">
                    <div className={cn(
                        'w-10 h-10 rounded-lg flex items-center justify-center text-xl border',
                        person.gender === 'male' ? 'bg-blue-500/10 border-blue-500/30' :
                            person.gender === 'female' ? 'bg-rose-400/10 border-rose-400/30' : 'bg-muted border-border'
                    )}>
                        {person.gender === 'male' ? '👨' : person.gender === 'female' ? '👩' : '👤'}
                    </div>
                    <div>
                        <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                            Thế hệ {person.generation}
                        </Badge>
                        <Badge variant={person.is_alive ? 'default' : 'secondary'} className="text-[10px] px-1.5 py-0 ml-1">
                            {person.is_alive ? 'Còn sống' : 'Đã mất'}
                        </Badge>
                    </div>
                </div>
                <Button variant="ghost" size="icon" className="h-6 w-6" onClick={onClose}>
                    <X className="w-3 h-3" />
                </Button>
            </div>
            <h3 className="font-bold text-base leading-tight mb-1">{person.full_name}</h3>
            <div className="space-y-1 text-sm text-muted-foreground">
                {person.birth_year && (
                    <div className="flex justify-between">
                        <span>Năm sinh:</span>
                        <span className="text-foreground font-medium">{person.birth_year}</span>
                    </div>
                )}
                {person.death_year && (
                    <div className="flex justify-between">
                        <span>Năm mất:</span>
                        <span className="text-foreground font-medium">{person.death_year}</span>
                    </div>
                )}
                {person.notes && (
                    <p className="text-xs mt-2 italic border-t border-border pt-2">{person.notes}</p>
                )}
            </div>
        </div>
    )
}

function TreeCanvas({ people }: { people: Person[] }) {
    const { fitView, setCenter } = useReactFlow()
    const [nodes, setNodes, onNodesChange] = useNodesState<PersonNodeType>([])
    const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([])
    const [selected, setSelected] = useState<Person | null>(null)
    const [search, setSearch] = useState('')
    const rawNodes = useRef<PersonNodeType[]>([])
    rawNodes.current = nodes

    useEffect(() => {
        const { nodes: n, edges: e } = buildTreeLayout(people)
        setNodes(n)
        setEdges(e)
        setTimeout(() => fitView({ padding: 0.1 }), 100)
    }, [people, setNodes, setEdges, fitView])

    const filtered = useMemo(() => {
        if (!search.trim()) return new Set<string>()
        const q = search.toLowerCase()
        return new Set(people.filter(p => p.full_name.toLowerCase().includes(q)).map(p => p.id))
    }, [search, people])

    useEffect(() => {
        setNodes(ns => ns.map(n => ({
            ...n,
            data: {
                ...n.data,
                isHighlighted: filtered.size > 0 && filtered.has(n.id),
            },
        })))
        if (filtered.size === 1) {
            const [id] = filtered
            const node = rawNodes.current.find(n => n.id === id)
            if (node) setCenter(node.position.x + 90, node.position.y + 40, { zoom: 1.2, duration: 600 })
        }
    }, [filtered, setNodes, setCenter])

    const onNodeClick: NodeMouseHandler<PersonNodeType> = useCallback((_evt, node) => {
        const p = people.find(x => x.id === node.id)
        setSelected(p ?? null)
    }, [people])

    const stats = useMemo(() => ({
        total: people.length,
        alive: people.filter(p => p.is_alive).length,
        gens: new Set(people.map(p => p.generation)).size,
    }), [people])

    return (
        <div className="relative w-full h-full">
            {/* Toolbar */}
            <div className="absolute top-4 left-4 z-20 flex flex-col gap-2">
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
                    <Input
                        placeholder="Tìm thành viên..."
                        value={search}
                        onChange={e => setSearch(e.target.value)}
                        className="pl-8 pr-8 h-8 w-52 text-sm glass border-border/60"
                    />
                    {search && (
                        <button className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" onClick={() => setSearch('')}>
                            <X className="w-3 h-3" />
                        </button>
                    )}
                </div>
                <div className="glass rounded-lg px-3 py-2 space-y-1">
                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                        <Users className="w-3 h-3" />
                        <span>{stats.total} thành viên ({stats.alive} còn sống)</span>
                    </div>
                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                        <GitBranch className="w-3 h-3" />
                        <span>{stats.gens} thế hệ</span>
                    </div>
                </div>
                {search && (
                    <div className="glass rounded-lg px-3 py-1.5 text-xs text-amber-700 font-medium">
                        {filtered.size === 0 ? 'Không tìm thấy' : `Tìm thấy ${filtered.size} người`}
                    </div>
                )}
            </div>

            {selected && <PersonDetailPanel person={selected} onClose={() => setSelected(null)} />}

            <ReactFlow
                colorMode="dark"
                className="bg-transparent"
                style={{ backgroundColor: 'transparent', '--xy-background-color': 'transparent' } as React.CSSProperties}
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onNodeClick={onNodeClick}
                onPaneClick={() => setSelected(null)}
                nodeTypes={nodeTypes}
                fitView
                fitViewOptions={{ padding: 0.1 }}
                minZoom={0.1}
                maxZoom={2}
                proOptions={{ hideAttribution: true }}
            >
                <Controls className="!bg-background !border-border shadow-sm rounded-xl overflow-hidden [&>button]:!border-b-border [&>button]:!bg-background hover:[&>button]:!bg-muted [&>button>svg]:!fill-primary" />
                <MiniMap
                    nodeColor={(n: Node) => {
                        const gender = (n.data as PersonNodeType['data'])?.person?.gender
                        return gender === 'male' ? '#3b82f6' : gender === 'female' ? '#fb7185' : '#78350f'
                    }}
                    maskColor="rgba(0,0,0,0.05)"
                    className="!bg-background !border-border rounded-xl shadow-sm border overflow-hidden"
                />
            </ReactFlow>
        </div>
    )
}

export default function TreePage() {
    const [people, setPeople] = useState<Person[]>([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        getAllPeople()
            .then(data => { setPeople(data); setLoading(false) })
            .catch(console.error)
    }, [])

    return (
        <div className="h-full flex flex-col">
            <div className="shrink-0 px-6 py-4 border-b border-border glass">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg gold-gradient flex items-center justify-center">
                        <span>🌳</span>
                    </div>
                    <div>
                        <h1 className="text-base font-bold leading-none">Cây Gia Phả</h1>
                        <p className="text-xs text-muted-foreground mt-0.5">Trần Tộc Mỹ Nguyên</p>
                    </div>
                </div>
            </div>

            <div className="flex-1 relative overflow-hidden">
                {loading ? (
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="text-center space-y-3">
                            <div className="w-12 h-12 rounded-full gold-gradient mx-auto animate-pulse flex items-center justify-center text-2xl">🌳</div>
                            <p className="text-sm text-muted-foreground">Đang tải cây gia phả...</p>
                        </div>
                    </div>
                ) : (
                    <ReactFlowProvider>
                        <TreeCanvas people={people} />
                    </ReactFlowProvider>
                )}
            </div>
        </div>
    )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'

import {
    GitFork, Users, BookOpen, LogOut, Menu, X, Shield,
    Phone, CalendarDays, ImageIcon
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { createClient } from '@/lib/supabase-client'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { useState, useEffect } from 'react'
import { Profile } from '@/lib/types'


const HeritageOverlay = () => (
    <>
        <div
            className="absolute inset-0 opacity-15 mix-blend-overlay pointer-events-none"
            style={{
                backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`
            }}
        />
        <div className="absolute inset-0 bg-gradient-to-br from-amber-600/40 to-amber-950/90 mix-blend-multiply pointer-events-none" />
        <div className="absolute inset-0 shadow-[inset_0_0_100px_rgba(0,0,0,0.5)] pointer-events-none" />
    </>
)

const navItems = [
    { href: '/tree', label: 'Cây Gia Phả', icon: GitFork },
    { href: '/people', label: 'Thành Viên', icon: Users },
    { href: '/directory', label: 'Danh Bạ', icon: Phone },
    { href: '/book', label: 'Sách Gia Phả', icon: BookOpen },
    { href: '/events', label: 'Sự Kiện', icon: CalendarDays },
    { href: '/media', label: 'Thư Viện', icon: ImageIcon },
]

interface SidebarProps {
    profile: Profile | null
}

export function Sidebar({ profile }: SidebarProps) {
    const pathname = usePathname()
    const router = useRouter()
    const supabase = createClient()
    const [open, setOpen] = useState(false)


    const handleLogout = async () => {
        await supabase.auth.signOut()
        toast.success('Đã đăng xuất')
        router.push('/')
        router.refresh()
    }

    const NavContent = () => (
        <div className="relative z-10 flex flex-col h-full text-amber-50">
            {/* Logo */}
            <div className="px-6 py-5 border-b border-white/10">
                <Link href="/tree" className="flex items-center gap-3 group" onClick={() => setOpen(false)}>
                    <div className="w-9 h-9 rounded-lg bg-white/10 backdrop-blur-sm border border-white/20 flex items-center justify-center shadow-lg">
                        <span className="text-lg drop-shadow-sm">🌳</span>
                    </div>
                    <div>
                        <p className="text-sm font-bold text-white leading-none tracking-wide">Trần Tộc</p>
                        <p className="text-xs text-amber-200/70 mt-0.5 font-medium">Mỹ Nguyên</p>
                    </div>
                </Link>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
                {navItems.map(({ href, label, icon: Icon }) => {
                    const isActive = pathname.startsWith(href)
                    return (
                        <Link
                            key={href}
                            href={href}
                            onClick={() => setOpen(false)}
                            className={cn(
                                'flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200',
                                isActive
                                    ? 'bg-primary/20 text-white border border-primary/30 shadow-sm'
                                    : 'text-amber-100/70 hover:bg-white/10 hover:text-white'
                            )}
                        >
                            <Icon className="w-4 h-4 shrink-0" />
                            {label}
                        </Link>
                    )
                })}

                {profile?.role === 'admin' && (
                    <>
                        <div className="pt-4 pb-1 px-3 mt-4 border-t border-white/10">
                            <p className="text-[10px] uppercase tracking-wider text-amber-200/50 font-bold">Quản trị</p>
                        </div>
                        <Link
                            href="/admin"
                            onClick={() => setOpen(false)}
                            className={cn(
                                'flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200',
                                pathname.startsWith('/admin')
                                    ? 'bg-primary/20 text-white border border-primary/30 shadow-sm'
                                    : 'text-amber-100/70 hover:bg-white/10 hover:text-white'
                            )}
                        >
                            <Shield className="w-4 h-4 shrink-0" />
                            Admin Panel
                        </Link>
                    </>
                )}
            </nav>

            {/* Bottom */}
            <div className="px-3 py-4 border-t border-white/10 space-y-3">
                <div className="flex items-center gap-3 px-3 py-2">
                    <div className="w-8 h-8 rounded-full bg-white/10 border border-white/20 flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-inner">
                        {profile?.full_name?.[0]?.toUpperCase() ?? '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                        <p className="text-xs font-semibold text-white truncate">
                            {profile?.full_name ?? 'Thành viên'}
                        </p>
                        <p className="text-[10px] text-amber-200/60 truncate uppercase tracking-wider font-medium mt-0.5">
                            {profile?.role === 'admin' ? '👑 Quản trị viên' : '👁 Người xem'}
                        </p>
                    </div>
                </div>

                <div className="flex flex-col gap-1">

                    <Button
                        variant="ghost"
                        size="sm"
                        className="w-full justify-start gap-2 text-amber-100/70 hover:text-red-400 hover:bg-red-500/20 transition-colors"
                        onClick={handleLogout}
                    >
                        <LogOut className="w-4 h-4" />
                        <span className="text-sm font-medium">Đăng xuất</span>
                    </Button>
                </div>
            </div>
        </div>

    )

    return (
        <>
            {/* Mobile top bar */}
            <div className="md:hidden fixed top-0 left-0 right-0 z-40 glass border-b border-border/50 px-4 py-3 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-md gold-gradient flex items-center justify-center shadow-sm">
                        <span className="text-sm drop-shadow-sm">🌳</span>
                    </div>
                    <span className="font-bold text-sm">Trần Tộc Mỹ Nguyên</span>
                </div>
                <Button variant="ghost" size="icon" className="h-8 w-8 hover:bg-foreground/5" onClick={() => setOpen(!open)}>
                    {open ? <X className="w-4 h-4" /> : <Menu className="w-4 h-4" />}
                </Button>
            </div>

            {/* Mobile overlay */}
            {open && (
                <div
                    className="md:hidden fixed inset-0 z-30 bg-black/60 backdrop-blur-sm"
                    onClick={() => setOpen(false)}
                />
            )}

            <aside className={cn(
                'md:hidden fixed top-0 left-0 z-40 h-full w-64 flex flex-col',
                'bg-background shadow-2xl overflow-hidden',
                'transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]',
                open ? 'translate-x-0' : '-translate-x-full'
            )}>
                <HeritageOverlay />
                <NavContent />
            </aside>

            {/* Desktop sidebar */}
            <aside className="hidden md:flex flex-col w-64 shrink-0 h-screen sticky top-0 bg-background border-r border-border overflow-hidden">
                <HeritageOverlay />
                <NavContent />
            </aside>
        </>
    )
}

'use client'

import { memo } from 'react'
import { Handle, Position, type NodeProps } from '@xyflow/react'
import { PersonNode as PersonNodeType } from '@/lib/tree-layout'
import { cn } from '@/lib/utils'

function PersonNodeComponent({ data, selected }: NodeProps<PersonNodeType>) {
    const { person, isHighlighted } = data
    const isMale = person.gender === 'male'
    const isFemale = person.gender === 'female'
    const yearRange = [person.birth_year, person.death_year].filter(Boolean).join(' – ')

    return (
        <div className={cn(
            'w-[160px] min-h-[120px] rounded-[20px] border transition-all duration-300 cursor-pointer group flex flex-col items-center justify-center text-center p-4 relative',
            'bg-white/[0.04] backdrop-blur-md shadow-xl',
            selected
                ? 'border-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.3)] ring-1 ring-amber-400/50 scale-105'
                : isHighlighted
                    ? 'border-amber-400/50 shadow-md scale-105'
                    : 'border-white/10 hover:bg-white/10 hover:border-white/20',
            !person.is_alive && 'opacity-75 grayscale-[20%]'
        )}>
            <Handle type="target" position={Position.Top} className="!w-2 !h-2 !bg-amber-400 !border-transparent !rounded-full opacity-0 group-hover:opacity-100 transition-opacity" />

            {/* Generation badge */}
            <div className="absolute top-2 right-2 text-[9px] font-semibold tracking-wider px-1.5 py-0.5 rounded-full bg-white/10 text-white/70">
                F{person.generation}
            </div>

            {/* Icon Box */}
            <div className={cn(
                'w-10 h-10 rounded-xl flex items-center justify-center text-xl mb-3 shrink-0 transition-transform group-hover:scale-110 duration-500',
                'bg-white/5 border border-white/10 shadow-inner',
                isMale ? 'text-blue-400' :
                    isFemale ? 'text-rose-400' :
                        'text-amber-400'
            )}>
                {person.avatar_url
                    ? <img src={person.avatar_url} alt={person.full_name} className="w-full h-full object-cover rounded-xl" />
                    : isMale ? '👨' : isFemale ? '👩' : '👤'
                }
            </div>

            {/* Title */}
            <h3 className="text-xs font-bold text-white mb-1 leading-tight tracking-wide px-1">
                {person.full_name}
            </h3>

            {/* Description */}
            {yearRange && (
                <p className="text-[10px] text-white/50 leading-relaxed font-medium">
                    {yearRange}
                </p>
            )}

            {!person.is_alive && (
                <span className="text-[9px] text-white/30 italic mt-1.5">đã mất</span>
            )}

            <Handle type="source" position={Position.Bottom} className="!w-2 !h-2 !bg-amber-400 !border-transparent !rounded-full opacity-0 group-hover:opacity-100 transition-opacity" />
        </div>
    )
}

export const PersonNode = memo(PersonNodeComponent)
